fn defensive_crisis(version, rnd, player, data, target, debug) -> DefensiveCrisis

// ── L19
tps = data.context.setting.tick_per_second            // &GameSetting +0x12f8

// ── L21~29 : 상대 팀 챔피언 중 'target 근처에서 실제로 보이는' 것만 수집
enemy_team = 1 - player.info.team                      // player+0x930. 2팀 배열 → 인덱스 2 이상이면 panic_bounds_check
near_enemies: bumpalo::Vec<&Entity> =
    cache.iter_champions(enemy_team)                   // = cache.player_champion[enemy_team] : [Option<&Entity>;5] 를 훑어 None 제거(simulation.rs:1904)
        .filter(|c| /* closure#0, buff_value.rs:22~26 — 본문은 담당 범위 밖(m10.ll 55868~55976) */ {
            r = plan_legacy::old::battle::max_range(c, target)              // L23
            if c.distance_sq(target) > (r + 30000)^2 { return false }        // L24  (dx=abs_diff, dy=abs_diff, 제곱합 비교)
            if fight_model::is_ignored_well_enemy(..) { return false }       // L25  = c.team == TeamType::Player(enemy_team) && path_finder::is_enemy_well_danger(version, player, c.x, c.y)
            data.blackboard[enemy_team].is_recent_visible(cache.game, player, c)  // L26
        })
        .collect_in(data.context.pool)

// ── L30~39 : die_imminent
if near_enemies.is_empty() {                            // Vec+0x18 == 0
    die_imminent = false
    cc_threat    = false                               // 루프가 0회라 자동으로 false → 여기서 그대로 반환
} else {
    // L32
    match cache.player_by_champion_id(target.id) {     // target+0x5c0. 반환은 null 가능 포인터(=Option<&PlayerState>)
        None => die_imminent = false,
        Some(tp) => {
            // L33 : towers 자리엔 bump 위의 **빈** Vec 를 새로 만들어 넘긴다
            //       (ptr=inttoptr 8(dangling), bump=data.context.pool, len=0, cap=0)
            die = fight_check::check_kill_die_tick(version, rnd, data,
                      /*judger=*/tp, /*focus=*/target,
                      /*enemy=*/near_enemies.clone(), /*towers=*/Vec::new_in(pool), debug)
            // L35
            die_imminent = die < tps * 2                // `shl %tps, 1`
        }
    }
}

// ── L41~49 : cc_threat = 근처 적 중 '지금 쓸 수 있는 CC 스킬'을 가진 놈이 하나라도 있나
//   (IR 에선 바깥 루프 = near_enemies 순회, 안쪽 3원소 any 는 완전 언롤됨)
cc_threat = near_enemies.iter().any(|e| {              // L41
    slots = [                                          // L42, [(&Option<Effect>, usize); 3]
        (e.skill_effect(),  e.skill_cooldown()),        // L43  → (+0x4c8, ty==Champion ? +0xb8 : 0)
        (e.skill2_effect(), e.skill2_cooldown()),       // L44  → (level>2 ? +0x500 : &NONE, ty==Champion ? +0xc0 : 0)
        (e.ult_effect(),    e.ult_cooldown()),          // L45  → (level>4 ? +0x538 : &NONE, ty==Champion ? +0xc8 : 0)
    ]
    slots.iter().any(|(eff, cd)| {                      // L47
        *cd <= tps                                      // 쿨타임 1초 이내면 '곧 쓸 수 있음'. IR: `icmp ugt cd, tps` 면 탈락
        && eff.as_ref().is_some_and(|x|                 // Effect+0x30(i32) == -1 이면 None → 탈락
               fight_check::effect_cc_time(version, x).is_some())   // L48. 반환 Option<usize> 의 .0 == 1 이면 Some
    })
})

// ── L53
return DefensiveCrisis { die_imminent, cc_threat }

// 주의(IR 형태): 3원소 any 는 세 벌로 완전 언롤되어 (cd>tps? → None? → effect_cc_time) 를 슬롯0/1/2 순서로
//   그대로 반복한다. 어느 슬롯에서든 Some 이 나오면 즉시 %149 로 빠져 cc_threat=true.
//   ty!=Champion 인 엔티티는 쿨다운 3개가 전부 0 이라 cd<=tps 를 항상 통과하고, 실제 탈락은 effect None 여부로만 결정된다.
//   attack_effect(+0x490)은 슬롯에 들어가지 않는다 — 평타는 CC 위협 판정 대상이 아니다.
